from pathlib import Path
import base64
ROOT=Path(__file__).resolve().parents[1]
A=ROOT/'assets/brand'
def data(name):
    return 'data:image/svg+xml;base64,'+base64.b64encode((A/name).read_bytes()).decode()
html='''<!doctype html><html lang="zh-Hant-TW"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>網站雷達 · Logo</title><style>
*{box-sizing:border-box}body{margin:0;color:var(--foreground,#242426);font:14px/1.65 -apple-system,BlinkMacSystemFont,"Noto Sans CJK TC","Noto Sans TC",sans-serif}button,a{font:inherit}button{cursor:pointer}figure{margin:0}p{margin:0}h2{font-size:17px;margin:0;font-weight:650} .hero{position:relative;overflow:hidden;background:#0a0a0a;color:#ededed;padding:28px 30px 26px;border-radius:var(--radius,12px)}.eyebrow{font:10px/1.5 ui-monospace,monospace;letter-spacing:2px;color:#a1a1aa}.hero:before{content:"";position:absolute;width:350px;height:350px;border:1px solid #27272a;border-radius:50%;right:-200px;top:-180px;box-shadow:0 0 0 45px #ffffff02,0 0 0 90px #ffffff02}.hero-logo{display:block;width:500px;max-width:100%;margin:50px auto 44px}.hero-bottom{display:flex;justify-content:space-between;gap:16px;align-items:center;border-top:1px solid #27272a;padding-top:18px}.hero-bottom strong{font-size:16px;font-weight:500;letter-spacing:1px}.hero-bottom small{color:#a1a1aa;font-size:10px;letter-spacing:1px}.intro{padding:22px 0;display:grid;grid-template-columns:1fr 1fr;gap:20px}.intro p{font-size:12px;color:var(--muted-foreground,#71717a);margin-top:6px}.switcher{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px}.tabs{display:flex;gap:4px;background:var(--muted,#f4f4f5);border-radius:7px;padding:3px}.tabs button{border:0;background:transparent;color:var(--muted-foreground,#71717a);font-size:12px;padding:5px 12px;border-radius:5px}.tabs button[aria-pressed=true]{background:var(--background,#fff);color:var(--foreground,#18181b);box-shadow:0 1px 3px #0001}.caption{font:10px ui-monospace,monospace;color:var(--muted-foreground,#71717a);letter-spacing:1px}.variants{display:grid;grid-template-columns:1fr 1fr;gap:12px}.variant{padding:20px;background:#f6f5f1;color:#18181b;border-radius:var(--radius,12px);min-width:0}.variant.dark{background:#18181b;color:#ededed}.variant-head{display:flex;justify-content:space-between;gap:8px;font-size:10px;letter-spacing:1px}.variant-head span{opacity:.55}.logo-stage{height:152px;display:flex;align-items:center;justify-content:center}.logo-stage img{display:block;width:100%;max-width:290px;max-height:135px;object-fit:contain}.download{color:inherit;text-decoration:none;border-bottom:1px solid #81818a55;font-size:11px;padding-bottom:3px}.download:hover{border-color:currentColor}.detail{display:grid;grid-template-columns:1.2fr 1fr;gap:12px;margin-top:12px}.small-sizes,.mono{padding:20px;border:1px solid var(--border,#dedee3);border-radius:var(--radius,12px)}.sizes{display:flex;align-items:end;justify-content:space-between;gap:15px;margin-top:20px}.size{text-align:center;font:10px ui-monospace,monospace;color:var(--muted-foreground,#71717a)}.size img{display:block;margin:0 auto 8px}.mono-stage{display:flex;gap:12px;margin-top:20px}.mono-swatch{display:flex;align-items:center;justify-content:center;width:56px;height:56px;border-radius:8px;background:#f6f5f1}.mono-swatch:last-child{background:#18181b}.mono-swatch img{width:40px;height:40px}.palette{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:22px}.color{height:7px;border-radius:3px;background:var(--swatch)}.color-name{font-size:11px;margin-top:7px}.hex{font:10px ui-monospace,monospace;color:var(--muted-foreground,#71717a);margin-top:3px}.foot{margin-top:18px;padding-top:14px;border-top:1px solid var(--border,#dedee3);font-size:11px;color:var(--muted-foreground,#71717a)}
@media(max-width:500px){.hero{padding:22px}.hero-logo{margin:38px auto 32px}.hero-bottom{display:block}.hero-bottom small{display:block;margin-top:6px}.hero-bottom strong{font-size:15px}.intro{grid-template-columns:1fr;gap:18px}.intro p{font-size:11px}.variants{grid-template-columns:1fr;gap:10px}.variant{padding:16px}.logo-stage{height:128px}.logo-stage img{max-height:110px}.variant-head{font-size:9px;letter-spacing:0}.variant-head span{display:none}.detail{grid-template-columns:1fr 1fr;gap:10px}.small-sizes,.mono{padding:16px}.sizes{gap:8px}.sizes .size:first-child{display:none}.caption{font-size:9px;letter-spacing:0}.palette{gap:8px}.color-name{font-size:10px}.hex{font-size:9px}}
</style></head><body>
<section class="hero"><div class="eyebrow">SITE RADAR</div><img class="hero-logo" src="HERO" alt="網站雷達，觀測環與流量刻度標誌"><div class="hero-bottom"><strong>看見網站的技術、流量與關聯。</strong><small>SITE.OBSERVE.TW</small></div></section>
<div class="intro"><div><h2>從流量到技術，觀察每個網站。</h2><p>開放圓環代表持續觀察；三道高低刻度呈現流量變化。右上角的橘色訊號點，成為品牌的識別焦點。</p></div><div><h2>與觀察站系列一致的字體。</h2><p>延續網站的暖橘與炭黑，中文字標改採 Noto Serif TC SemiBold，呼應新文易數與部落格觀察的宋體風格；採用 C 版，移除網址並放大中文，讓站名成為視覺焦點。</p></div></div>
<div class="switcher"><span class="caption">LOGO SYSTEM / 標誌組合</span><div class="tabs" role="group" aria-label="標誌排列"><button type="button" aria-pressed="true" data-layout="horizontal">橫式</button><button type="button" aria-pressed="false" data-layout="stacked">直式</button></div></div>
<div class="variants"><figure class="variant"><figcaption class="variant-head">淺底標準版<span>LIGHT</span></figcaption><div class="logo-stage"><img id="light-logo" src="LIGHT" alt="淺色背景用 Logo"></div><a class="download" id="light-download" href="LIGHT" download="logo-horizontal-light.svg">下載 SVG ↓</a></figure><figure class="variant dark"><figcaption class="variant-head">深底標準版<span>DARK</span></figcaption><div class="logo-stage"><img id="dark-logo" src="HERO" alt="深色背景用 Logo"></div><a class="download" id="dark-download" href="HERO" download="logo-horizontal-dark.svg">下載 SVG ↓</a></figure></div>
<div class="detail"><section class="small-sizes"><span class="caption">小尺寸 / 圖示</span><div class="sizes"><div class="size"><img src="FAV" width="48" height="48" alt="48 像素圖示">48 px</div><div class="size"><img src="FAV" width="32" height="32" alt="32 像素圖示">32 px</div><div class="size"><img src="FAV" width="16" height="16" alt="16 像素圖示">16 px</div></div></section><section class="mono"><span class="caption">單色 / 印刷與浮水印</span><div class="mono-stage"><div class="mono-swatch"><img src="BLACK" alt="單黑色標誌"></div><div class="mono-swatch"><img src="WHITE" alt="反白標誌"></div></div></section></div>
<div class="palette"><div><div class="color" style="--swatch:#fb923c"></div><div class="color-name">觀測橘 · 深底</div><p class="hex">#FB923C</p></div><div><div class="color" style="--swatch:#c2410c"></div><div class="color-name">赭橘 · 淺底</div><p class="hex">#C2410C</p></div><div><div class="color" style="--swatch:#18181b"></div><div class="color-name">炭黑</div><p class="hex">#18181B</p></div><div><div class="color" style="--swatch:#ededed;border:1px solid #d4d4d8"></div><div class="color-name">霧白</div><p class="hex">#EDEDED</p></div></div>
<p class="foot">全套包含：橫式、直式、獨立圖標、深淺底與單色版本、透明 PNG、favicon 與手機圖示。中文字標已轉為向量路徑，跨裝置不會跑字。</p>
<script>const assets=ASSETS;document.querySelectorAll('[data-layout]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-layout]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));for(const variant of ['light','dark']){const name='logo-'+button.dataset.layout+'-'+variant+'.svg';document.getElementById(variant+'-logo').src=assets[name];const a=document.getElementById(variant+'-download');a.href=assets[name];a.download=name}}));</script>
</body></html>'''
import json
mapping={'HERO':'logo-horizontal-dark.svg','LIGHT':'logo-horizontal-light.svg','FAV':'favicon.svg','BLACK':'logo-mark-black.svg','WHITE':'logo-mark-white.svg'}
for key,name in mapping.items():html=html.replace('="'+key+'"','="'+data(name)+'"')
assets={f'logo-{layout}-{variant}.svg':data(f'logo-{layout}-{variant}.svg') for layout in ['horizontal','stacked'] for variant in ['dark','light']}
html=html.replace('ASSETS',json.dumps(assets))
(ROOT/'docs/brand/index.html').write_text(html)
